{{ config(materialized='incremental', incremental_strategy='delete+insert', unique_key='order_id') }}

with ranked as (
    select
        order_id,
        status,
        net_cents,
        updated_at,
        event_id,
        row_number() over (
            partition by order_id
            order by updated_at desc, event_id desc
        ) as rn
    from {{ ref('order_events') }}
    {% if is_incremental() %}
    -- only orders touched by events newer than the current watermark
    where order_id in (
        select order_id
        from {{ ref('order_events') }}
        where updated_at >= (select coalesce(max(updated_at), cast('1900-01-01' as timestamp)) from {{ this }})
    )
    {% endif %}
)

select order_id, status, net_cents
from ranked
where rn = 1

{{ config(materialized='incremental', incremental_strategy='delete+insert', unique_key='order_id') }}

with watermark as (
    {% if is_incremental() %}
    select coalesce(max(updated_at), cast('1900-01-01' as timestamp)) as wm from {{ this }}
    {% else %}
    select cast('1900-01-01' as timestamp) as wm
    {% endif %}
),

ranked as (
    select
        order_id,
        status,
        net_cents,
        updated_at,
        event_id,
        row_number() over (
            partition by order_id
            order by updated_at desc, event_id desc
        ) as rn
    from {{ ref('order_events') }}
    where order_id in (
        -- only orders touched by events at/after the current watermark
        select e.order_id
        from {{ ref('order_events') }} e
        cross join watermark w
        where e.updated_at >= w.wm
    )
)

select order_id, status, net_cents
from ranked
where rn = 1
